    .burger-backdrop {
      position: absolute;
      inset: 0;
      background: rgba(2, 6, 23, 0.62);
      backdrop-filter: blur(3px);
      z-index: 55;
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.22s ease;
    }
    .burger-backdrop.open {
      opacity: 1;
      pointer-events: auto;
    }
    .burger-drawer {
      position: absolute;
      top: 0;
      bottom: 0;
      left: 0;
      width: 78%;
      max-width: 300px;
      background: var(--bg-surface);
      border-right: 1.5px solid var(--primary);
