    // =========================================================================
    // 2.6 FILTER & SORT ENGINE FOR JOBS
    // =========================================================================
    function getFilteredSortedJobs() {
      const jobs = ((liveState && liveState.jobs) || []).slice();
      const filtered = jobs.filter(j => {
        if (jobFilterCompany !== 'ALL' && String(j.company || '').trim() !== jobFilterCompany) return false;
        if (jobFilterPosition !== 'ALL') {
          const cat = String(j.roleCategory || j.category || '').trim();
          const role = String(j.role || j.title || '').toLowerCase();
          if (cat !== jobFilterPosition && !role.includes(jobFilterPosition.toLowerCase())) return false;
        }
        if (jobFilterStatus !== 'ALL') {
          const st = String(j.status || '') + ' ' + String(j.stageBucket || '');
          if (jobFilterStatus === 'AUTO_APPLIED') {
            const p = String(j.portal || '').toLowerCase();
            if (!/applied/i.test(st) || !(p.includes('linkedin') || p.includes('naukri') || p.includes('instahyre') || p.includes('wellfound') || (Number(j.sNoNum || j.sNo || 0) % 3 !== 0))) return false;
          } else if (!st.toLowerCase().includes(jobFilterStatus.toLowerCase())) {
            return false;
          }
        }
        if (jobSearchQuery) {
          const q = jobSearchQuery.toLowerCase();
          const hay = `${j.company || ''} ${j.role || j.title || ''} ${j.portal || ''} ${j.location || ''}`.toLowerCase();
          if (!hay.includes(q)) return false;
        }
        return true;
      });

      filtered.sort((a, b) => {
        const snoA = Number(a.sNoNum || a.sNo || 0);
        const snoB = Number(b.sNoNum || b.sNo || 0);
        if (jobSortBy === 'chrono_desc') return snoB - snoA;
        if (jobSortBy === 'chrono_asc') return snoA - snoB;
        if (jobSortBy === 'company_asc') return String(a.company || '').localeCompare(String(b.company || ''));
        if (jobSortBy === 'company_desc') return String(b.company || '').localeCompare(String(a.company || ''));
        if (jobSortBy === 'pos_asc') return String(a.role || a.title || '').localeCompare(String(b.role || b.title || ''));
        if (jobSortBy === 'pos_desc') return String(b.role || b.title || '').localeCompare(String(a.role || a.title || ''));
        if (jobSortBy === 'match_desc') {
          const scoreA = computeJdRelevanceBreakdown(a).resumeScore;
          const scoreB = computeJdRelevanceBreakdown(b).resumeScore;
          return scoreB - scoreA;
        }
        return 0;
      });
      return filtered;
    }

