    function enforceMobileViewportScale() {
      const isMobileMode = document.body.classList.contains('mobile-only-mode');
      if (!isMobileMode) {
        document.documentElement.style.zoom = '';
        return;
      }
      const ua = navigator.userAgent || '';
      const isMobileDevice = /Android|iPhone|iPad|iPod|Mobile|CareerPulseNativeAndroid/i.test(ua);
      if (isMobileDevice && window.innerWidth > 540) {
        const sw = Math.min(Math.max(window.screen.width || 390, 340), 430);
        const ratio = window.innerWidth / sw;
        if (ratio > 1.2 && ratio < 3.6) {
          document.documentElement.style.zoom = ratio.toFixed(3);
        }
      }
    }

    function applyMobileAccessibilityPolish() {
      const frame = document.getElementById('phone-frame-el');
      if (!frame) return;
      const isMobileOnly = document.body.classList.contains('mobile-only-mode');
      enforceMobileViewportScale();

      // 1. Ensure every input, select, and textarea has an accessible label (aria-label + title)
      frame.querySelectorAll('input, select, textarea').forEach((el, idx) => {
        if (!el.getAttribute('aria-label')) {
          const ph = el.getAttribute('placeholder') || el.getAttribute('title') || '';
          const firstOpt = el.tagName === 'SELECT' && el.options && el.options[0] ? el.options[0].text : '';
          const fallback = ph || firstOpt || el.id || ('Mobile Form Control ' + (idx + 1));
          el.setAttribute('aria-label', fallback);
          if (!el.getAttribute('title')) el.setAttribute('title', fallback);
        }
        if (el.type === 'checkbox') {
          el.style.minWidth = '28px';
          el.style.minHeight = '28px';
          el.style.width = '28px';
          el.style.height = '28px';
          el.style.cursor = 'pointer';
        }
      });
      // 2. Enforce comfortable touch target minimum on all buttons and interactive elements inside phone frame
      const minTap = isMobileOnly ? '38px' : '28px';
      frame.querySelectorAll('button, a, [onclick], input[type="checkbox"], select').forEach(btn => {
        btn.style.minHeight = minTap;
        btn.style.minWidth = minTap;
        if (btn.tagName === 'SPAN') {
          btn.style.display = 'inline-flex';
          btn.style.alignItems = 'center';
          btn.style.justifyContent = 'center';
        }
      });
      // 3. Upgrade inline font sizes & cramped multi-column grids when in mobile-only-mode
      frame.querySelectorAll('*').forEach(el => {
        const inlineFs = el.style && el.style.fontSize;
        if (inlineFs && /^[0-9.]+px$/i.test(inlineFs)) {
          const origNum = parseFloat(el.getAttribute('data-orig-fs') || inlineFs);
          if (!el.getAttribute('data-orig-fs')) {
            el.setAttribute('data-orig-fs', String(origNum));
          }
          if (isMobileOnly) {
            if (origNum <= 9.5) {
              el.style.fontSize = '12px';
            } else if (origNum <= 10.8) {
              el.style.fontSize = '13px';
            } else if (origNum <= 12.2) {
              el.style.fontSize = '14px';
            } else if (origNum <= 14.5) {
              el.style.fontSize = '15.5px';
            } else if (origNum <= 19) {
              el.style.fontSize = (origNum + 2.5) + 'px';
            }
          } else if (origNum < 10) {
            el.style.fontSize = '10px';
          }
        }
        if (isMobileOnly && el.style && el.style.gridTemplateColumns) {
          const gtc = el.style.gridTemplateColumns.replace(/\s+/g, '');
          if (gtc.includes('repeat(4,1fr)')) {
            el.style.gridTemplateColumns = 'repeat(2, 1fr)';
            el.style.gap = '8px';
          } else if (gtc === '1fr1fr1.1fr') {
            el.style.gridTemplateColumns = '1fr 1fr';
            el.style.gap = '8px';
          }
        }
      });
    }

