    async function toggleMobileTodoItem(todoId, isDone) {
      if (liveState && Array.isArray(liveState.todos)) {
        const item = liveState.todos.find(x => x.todo_id === todoId);
        if (item) item.status = isDone ? 'done' : 'pending';
        renderSimulator();
      }
      try {
        const r = await fetch('/webhook/job-dashboard-api', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ action: 'todo_action', subAction: 'toggle', todoId, status: isDone ? 'done' : 'pending' })
        });
        const d = await r.json();
        if (d && Array.isArray(d.todos) && liveState) {
          liveState.todos = d.todos;
          renderSimulator();
        }
        notifyToast(isDone ? `Completed ${todoId}!` : `Reopened ${todoId}`);
      } catch (e) {}
    }

    async function addMobileTodoItem() {
      const inp = document.getElementById('m-new-todo-input');
      const title = (inp ? inp.value : '').trim();
      if (!title) return;
      inp.value = '';
      notifyToast('Adding requirement to PostgreSQL...');
      try {
        const r = await fetch('/webhook/job-dashboard-api', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ action: 'todo_action', subAction: 'add', title, category: '6. Mobile UI & UX Polish', priority: 'P0' })
        });
        const d = await r.json();
        if (d && Array.isArray(d.todos) && liveState) {
          liveState.todos = d.todos;
          renderSimulator();
