    let pendingSignoffContext = null; // { sNo, targetStatus, fromSwipeDir }

    function openCandidateSignoffModal(sNo, targetStatus, fromSwipeDir) {
      const jobs = (liveState && liveState.jobs) || [];
      const job = jobs.find(j => String(j.sNo) === String(sNo)) || getSelectedJob();
      pendingSignoffContext = { sNo: String(job.sNo || sNo), targetStatus: targetStatus || 'Approved', fromSwipeDir: fromSwipeDir || null };
      const lbl = document.getElementById('signoff-modal-job-label');
      if (lbl) lbl.textContent = `#${job.sNo} ${job.company || 'Company'} — ${job.role || job.title || 'Target Role'}`;
      const chk = document.getElementById('signoff-modal-checkbox');
      if (chk) chk.checked = Boolean(job._signedOff);
      const modal = document.getElementById('signoff-modal-backdrop');
      if (modal) modal.style.display = 'flex';
      toggleSignoffConfirmBtn();
    }

    function closeCandidateSignoffModal() {
      const modal = document.getElementById('signoff-modal-backdrop');
      if (modal) modal.style.display = 'none';
      pendingSignoffContext = null;
      renderSimulator();
    }

    function toggleSignoffConfirmBtn() {
      const chk = document.getElementById('signoff-modal-checkbox');
      const btn = document.getElementById('signoff-confirm-btn');
      if (!btn) return;
      btn.style.opacity = (chk && chk.checked) ? '1' : '0.55';
    }

    let showA4EditDrawer = false;

    function editResumeBeforeSignoff() {
      const ctx = pendingSignoffContext;
      closeCandidateSignoffModal();
      if (ctx && ctx.sNo) selectedJobSno = String(ctx.sNo);
      if (currentPhoneTab === 'jobs') {
        sliderTab = 'ai';
        setSliderState('half');
      } else {
        showA4EditDrawer = true;
        setPhoneTab('a4');
      }
      notifyToast('Review and modify your Resume & Cover Letter before signing off.');
