        : (portalSubTab === 'companies' ? companiesOnly : pendingOnly);

      body.innerHTML = `
        <!-- Vault Summary Header -->
        <div class="m-card" style="border-color:rgba(99,102,241,0.45);background:linear-gradient(135deg,var(--bg-surface),var(--bg-surface-2));">
