              <div style="font-size:8.5px;color:var(--text-muted);">Logged In</div>
            </div>
            <div style="background:var(--bg-surface);padding:5px;border-radius:8px;border:1px solid var(--border-color);">
              <div style="font-size:13px;font-weight:800;color:var(--warning);">${pCounts.pending}</div>
              <div style="font-size:8.5px;color:var(--text-muted);">Pending Auth</div>
            </div>
            <div style="background:var(--bg-surface);padding:5px;border-radius:8px;border:1px solid var(--border-color);">
              <div style="font-size:13px;font-weight:800;color:var(--accent);">${pCounts.total}</div>
              <div style="font-size:8.5px;color:var(--text-muted);">Total Tracked</div>
            </div>
          </div>
        </div>

        <!-- Collapsible Add New Company Career Website / Job Portal Form -->
        <div class="m-card" style="display:${showAddPortalForm ? 'block' : 'none'};border-color:var(--primary);">
          <div style="font-size:10.5px;font-weight:800;color:var(--primary);margin-bottom:6px;">Connect New Job Portal or Company Career Website</div>
          <input id="new-portal-name" class="m-input mb-2" placeholder="Portal or Company Name (e.g., Razorpay Careers / Monster)" />
          <input id="new-portal-domain" class="m-input mb-2" placeholder="Career Site URL (e.g., razorpay.com/jobs or Lever/Workday URL)" />
          <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-bottom:6px;">
            <select id="new-portal-kind" class="m-select">
              <option value="company">Company Career Website</option>
              <option value="portal">Job Board / Portal</option>
            </select>
            <select id="new-portal-ats" class="m-select">
              <option value="Workday Universal SSO">Workday SSO</option>
              <option value="Greenhouse / Lever Token">Greenhouse / Lever</option>
              <option value="OAuth 2.0 / Google SSO">OAuth 2.0 / Google SSO</option>
              <option value="Playwright Session Cookie">Session Cookie / OTP</option>
            </select>
          </div>
          <input id="new-portal-user" class="m-input mb-2" placeholder="Login Email / Username" value="user@example.com" />
          <input id="new-portal-secret" type="password" class="m-input mb-2" placeholder="Password, App Secret, or Session Cookie (Encrypted AES-256)" />
          <button class="m-btn m-btn-success w-100" onclick="addCustomCompanyPortal()">
            Encrypt &amp; Authorize in Vault
          </button>
        </div>

        <!-- 3-Subtab Segmented Switcher -->
        <div class="seg-bar">
          <button class="seg-btn ${portalSubTab==='portals'?'active':''}" onclick="portalSubTab='portals';renderSimulator();">
            Job Portals (${portalsOnly.length})
          </button>
          <button class="seg-btn ${portalSubTab==='companies'?'active':''}" onclick="portalSubTab='companies';renderSimulator();">
            Company Sites (${companiesOnly.length})
          </button>
          <button class="seg-btn ${portalSubTab==='pending'?'active':''}" onclick="portalSubTab='pending';renderSimulator();">
            Pending (${pendingOnly.length})
          </button>
        </div>

        ${activeList.map(p => {
          const isConn = p.status === 'CONNECTED';
          const isOpen = Boolean(openPortalAuthIds[p.id]);
          return `
            <div class="m-card" style="border-left:3px solid ${isConn ? 'var(--success)' : 'var(--warning)'};">
              <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:6px;">
                <div>
                  <div style="font-size:12px;font-weight:800;">${escH(p.name)}</div>
                  <div style="font-size:9.5px;color:var(--accent);font-weight:700;">${escH(p.domain)} • ${escH(p.atsType)}</div>
                  <div style="font-size:9px;color:var(--text-muted);margin-top:2px;">
                    ${escH(p.account)} • <strong>${p.jobsCount}</strong> Jobs • <strong>${p.appliedCount}</strong> Applied
                  </div>
                </div>
                <span style="font-size:8.5px;padding:3px 7px;border-radius:99px;font-weight:800;background:${isConn ? 'var(--success-soft)' : 'var(--warning-soft)'};color:${isConn ? 'var(--success)' : 'var(--warning)'};white-space:nowrap;">
                  ${isConn ? 'Logged In' : 'Pending Auth'}
                </span>
              </div>

              <div style="display:flex;justify-content:space-between;align-items:center;gap:6px;margin-top:8px;padding-top:6px;border-top:1px solid var(--border-color);">
                <select class="m-select" style="width:auto;font-size:9.5px;padding:3px 7px;" onchange="updatePortalMode('${p.id}', this.value)">
                  <option value="AUTO_APPLY" ${p.mode==='AUTO_APPLY'?'selected':''}>Auto-Apply Enabled</option>
                  <option value="REVIEW_FIRST" ${p.mode==='REVIEW_FIRST'?'selected':''}>Review Before Apply</option>
                  <option value="DISCOVER_ONLY" ${p.mode==='DISCOVER_ONLY'?'selected':''}>Fetch JDs Only</option>
                </select>
                <div style="display:flex;gap:4px;">
                  ${!isConn ? `
                    <button class="m-btn m-btn-warning" style="padding:4px 9px;font-size:9.5px;" onclick="togglePortalAuthDrawer('${p.id}')">
                      ${isOpen ? 'Close ▲' : 'Authorize Now ▼'}
                    </button>
                  ` : `
                    <button class="m-btn m-btn-ghost" style="padding:4px 8px;font-size:9px;" onclick="togglePortalAuthDrawer('${p.id}')">
                      ${isOpen ? 'Close ▲' : 'Session / Re-Auth'}
                    </button>
                  `}
                </div>
              </div>

              <!-- 2. INLINE 3-METHOD PORTAL AUTHORIZATION DRAWER -->
              <div style="display:${isOpen ? 'block' : 'none'};margin-top:8px;padding-top:8px;border-top:1px dashed var(--border-color);">
                <div style="font-size:9.5px;font-weight:800;color:var(--warning);margin-bottom:5px;">
                  Authorize ${escH(p.name)} (AES-256-GCM PostgreSQL RLS Vault)
