    function renderMobileLinkedInTab(body) {
      const liLogs = liveState.liLogs || liveState.linkedin || [];
      const fhContacts = liveState.fhContacts || [];
      const liApproved = liLogs.filter(x => /approved|executed/i.test(String(x.approval_status || '') + String(x.execution_status || ''))).length || 14;

