              <div style="font-size:17px;font-weight:800;color:var(--primary);">${fhContacts.length} <span style="font-size:10px;color:var(--text-muted);">Connections</span></div>
            </div>
            <div style="font-size:9.5px;color:var(--text-secondary);text-align:right;">
              <div><strong>${liLogs.length}</strong> Posts • <strong>${liApproved}</strong> Approved</div>
              <div><strong>${milestoneState.length}</strong> Career Updates</div>
