          <button class="seg-btn ${liSubTab === 'connections' ? 'active' : ''}" onclick="liSubTab='connections';renderSimulator();">
            Connections (${fhContacts.length})
          </button>
          <button class="seg-btn ${liSubTab === 'milestones' ? 'active' : ''}" onclick="liSubTab='milestones';renderSimulator();">
            Updates (${milestoneState.length})
          </button>
        </div>
      `;

      if (liSubTab === 'actions') {
        // 2.1 APPROVAL, REJECT, REVIEW WITH FEEDBACK OF POSTS OR ACTIONS (WITH COLLAPSIBLE FILTER)
        const actCompanies = Array.from(new Set(liLogs.map(x => String(x.company_name || x.company || '').trim()).filter(Boolean))).sort();
        const filteredLogs = liLogs.filter(item => {
          if (liActionFilter !== 'ALL') {
            const st = String(item.approval_status || item.approvalStatus || '') + ' ' + String(item.execution_status || '');
            if (!st.toLowerCase().includes(liActionFilter.toLowerCase())) return false;
          }
          if (liActionCompany !== 'ALL') {
            const comp = String(item.company_name || item.company || '').trim();
            if (comp !== liActionCompany) return false;
          }
          if (liActionSearch) {
            const q = liActionSearch.toLowerCase();
            const hay = `${item.insider_name || item.targetPerson || ''} ${item.company_name || item.company || ''} ${item.content_text || item.draftedContent || ''} ${item.post_snippet || ''}`.toLowerCase();
            if (!hay.includes(q)) return false;
