        if (liActionPage >= totalActPages) liActionPage = totalActPages - 1;
        if (liActionPage < 0) liActionPage = 0;
        const pagedLogs = filteredLogs.slice(liActionPage * LI_PAGE_SIZE, (liActionPage + 1) * LI_PAGE_SIZE);

        body.innerHTML = navHtml + `
