            ${activeActFilters > 0 ? `<button class="m-btn m-btn-ghost" style="padding:6px 8px;" onclick="liActionFilter='ALL';liActionCompany='ALL';liActionSearch='';liActionPage=0;renderSimulator();">Reset</button>` : ''}
