            <label style="font-size:9px;color:var(--text-muted);font-weight:700;">FILTER BY APPROVAL STATUS</label>
            <div style="display:flex;gap:4px;flex-wrap:wrap;margin-top:3px;">
              ${[
                ['ALL', 'All (' + liLogs.length + ')'],
                ['Awaiting', '⏳ Pending'],
                ['Approved', '✅ Approved'],
                ['Reworked', '✍️ Reworked'],
