                  <button class="m-btn m-btn-success" style="flex:1;" onclick="handleMobileLiAction('${id}', 'approve')">
                    <i class="bi bi-check2-circle"></i> Approve
                  </button>
                  <button class="m-btn m-btn-danger" style="flex:1;" onclick="handleMobileLiAction('${id}', 'reject')">
