                  </div>
                  <textarea id="li-fb-input-${id}" class="m-textarea mb-1" rows="2" placeholder="Type your feedback to rewrite this post comment or action..."></textarea>
                  <div style="display:flex;gap:5px;">
                    <button class="m-btn m-btn-primary w-100" onclick="submitMobileLiFeedback('${id}')">
                      ✨ AI Rewrite Draft &amp; Save Rule
                    </button>
                  </div>
                </div>
              </div>
            `;
          }).join('')}
        `;
      } else if (liSubTab === 'connections') {
        // 2.2 CONNECTIONS LIST WITH COLLAPSIBLE FILTER BY COMPANY & POSITION + INLINE AI REWORK DRAWER
        const companies = Array.from(new Set(fhContacts.map(c => String(c.company_name || '').trim()).filter(Boolean))).sort();
        const positions = Array.from(new Set(fhContacts.map(c => String(c.role_title || c.category || '').trim()).filter(Boolean))).sort();

        const filteredConns = fhContacts.filter(c => {
          if (liConnCompany !== 'ALL' && String(c.company_name || '').trim() !== liConnCompany) return false;
          if (liConnPosition !== 'ALL') {
            const pos = String(c.role_title || '') + ' ' + String(c.category || '');
            if (!pos.toLowerCase().includes(liConnPosition.toLowerCase())) return false;
          }
          if (liConnSearch) {
            const q = liConnSearch.toLowerCase();
            const hay = `${c.person_name || ''} ${c.company_name || ''} ${c.role_title || ''} ${c.category || ''} ${c.location || ''}`.toLowerCase();
            if (!hay.includes(q)) return false;
          }
          return true;
        }).sort((a, b) => {
          if (liConnSort === 'name_asc') return String(a.person_name || '').localeCompare(String(b.person_name || ''));
          if (liConnSort === 'name_desc') return String(b.person_name || '').localeCompare(String(a.person_name || ''));
          if (liConnSort === 'comp_asc') return String(a.company_name || '').localeCompare(String(b.company_name || ''));
          if (liConnSort === 'pos_asc') return String(a.role_title || '').localeCompare(String(b.role_title || ''));
          return 0;
        });

        const activeConnFilters = (liConnCompany !== 'ALL' ? 1 : 0) + (liConnPosition !== 'ALL' ? 1 : 0) + (liConnSearch ? 1 : 0) + (liConnSort !== 'name_asc' ? 1 : 0);
        const totalConnPages = Math.max(1, Math.ceil(filteredConns.length / LI_PAGE_SIZE));
        if (liConnPage >= totalConnPages) liConnPage = totalConnPages - 1;
        if (liConnPage < 0) liConnPage = 0;
        const pagedConns = filteredConns.slice(liConnPage * LI_PAGE_SIZE, (liConnPage + 1) * LI_PAGE_SIZE);

        body.innerHTML = navHtml + `
          <!-- 1. COLLAPSIBLE FILTER TOGGLE BAR IN LINKEDIN CONNECTIONS TAB -->
          <div style="display:flex;justify-content:space-between;align-items:center;gap:6px;margin-bottom:8px;">
            <button class="m-btn ${showLiConnFilters || activeConnFilters > 0 ? 'm-btn-primary' : 'm-btn-ghost'}" style="flex:1;justify-content:space-between;padding:6px 10px;" onclick="showLiConnFilters=!showLiConnFilters;renderSimulator();">
              <span><i class="bi bi-sliders"></i> Filter &amp; Sort Connections (${filteredConns.length}/${fhContacts.length}) ${activeConnFilters > 0 ? '• ' + activeConnFilters + ' active' : ''}</span>
              <span>${showLiConnFilters ? '▲ Collapse' : '▼ Filter'}</span>
            </button>
            ${activeConnFilters > 0 ? `<button class="m-btn m-btn-ghost" style="padding:6px 8px;" onclick="liConnCompany='ALL';liConnPosition='ALL';liConnSearch='';liConnSort='name_asc';liConnPage=0;renderSimulator();">Reset</button>` : ''}
