              </span>
              <button class="m-btn m-btn-ghost" style="padding:2px 6px;font-size:10px;" onclick="liConnCompany='ALL';liConnPosition='ALL';liConnSearch='';liConnSort='name_asc';liConnPage=0;renderSimulator();">Reset All</button>
            </div>
            <input class="m-input mb-2" placeholder="🔍 Search name, company, position, city..." value="${escH(liConnSearch)}" oninput="liConnSearch=this.value;liConnPage=0;renderSimulator();" />
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-bottom:6px;">
              <div>
                <label style="font-size:10px;color:var(--text-muted);font-weight:700;">FILTER BY COMPANY</label>
                <select class="m-select" onchange="liConnCompany=this.value;liConnPage=0;renderSimulator();">
                  <option value="ALL">All Companies (${companies.length})</option>
                  ${companies.map(c => `<option value="${escH(c)}" ${liConnCompany===c?'selected':''}>${escH(c)}</option>`).join('')}
