                </select>
              </div>
            </div>
            <div>
              <label style="font-size:10px;color:var(--text-muted);font-weight:700;">SORT CONNECTIONS</label>
              <select class="m-select" onchange="liConnSort=this.value;liConnPage=0;renderSimulator();">
                <option value="name_asc" ${liConnSort==='name_asc'?'selected':''}>🔤 Name (A → Z)</option>
                <option value="name_desc" ${liConnSort==='name_desc'?'selected':''}>🔤 Name (Z → A)</option>
