                    <button class="m-btn m-btn-ghost" style="font-size:10px;padding:3px 6px;" onclick="setFhFbPreset('${cid}', 'Make the connection note under 11 words and ultra-concise')">⚡ Short (&lt;11w)</button>
                    <button class="m-btn m-btn-ghost" style="font-size:10px;padding:3px 6px;" onclick="setFhFbPreset('${cid}', 'Warmly ask for brief career advice or referral insight on their data team')">🤝 Ask Referral / Advice</button>
                    <button class="m-btn m-btn-ghost" style="font-size:10px;padding:3px 6px;" onclick="setFhFbPreset('${cid}', 'Connect as a fellow Senior Data & BI Analyst working on SQL, Python & executive dashboards')">💡 Peer SQL/BI Hook</button>
