    function saveProfileSettings() {
      syncProfileInputsToState();
      candidateProfileState.openMultiDropdown = null;
      updateBurgerProfileAvatar();
      notifyToast('✅ Profile saved!');
      renderSimulator();
    }

    let ownerSettingsUnlocked = false;
    try {
      ownerSettingsUnlocked = localStorage.getItem('cp_owner_unlocked') === '1';
    } catch (e) {}

    function unlockOwnerSettings() {
      const val = String(document.getElementById('owner-pin-input')?.value || '').trim().toLowerCase();
      if (val === '0808' || val === 'user@example.com' || val === 'sumantob') {
        ownerSettingsUnlocked = true;
        try { localStorage.setItem('cp_owner_unlocked', '1'); } catch (e) {}
        notifyToast('Owner Settings Unlocked!');
        renderSimulator();
      } else {
        notifyToast('Access Denied — Owner Passcode Required');
      }
    }

    function lockOwnerSettings() {
      ownerSettingsUnlocked = false;
      try { localStorage.removeItem('cp_owner_unlocked'); } catch (e) {}
      notifyToast('Settings locked to outside public!');
      renderSimulator();
    }

