            <div style="font-size:10.5px;color:var(--text-muted);margin-bottom:12px;">
              App &amp; Automation Settings are restricted to the owner (<code>user@example.com</code>). Enter your Owner PIN or email to unlock on this device:
            </div>
            <input id="owner-pin-input" type="password" class="m-input mb-2" placeholder="Enter Owner PIN (0808) or Owner Email" aria-label="Owner PIN or Email" style="text-align:center;font-weight:700;" onkeydown="if(event.key==='Enter')unlockOwnerSettings()" />
            <button type="button" class="m-btn m-btn-primary w-100" onclick="unlockOwnerSettings()">
              Unlock Owner Settings
            </button>
          </div>
        `;
        return;
      }
      body.innerHTML = `
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">
          <button class="m-btn m-btn-ghost" style="padding:4px 10px;font-size:10.5px;font-weight:800;" onclick="goBackPhoneTab()">
            <i class="bi bi-arrow-left"></i> Back
          </button>
          <div style="display:flex;align-items:center;gap:6px;">
            <span style="font-size:10px;color:var(--success);font-weight:800;">Owner Unlocked</span>
            <button type="button" class="m-btn m-btn-danger" style="padding:3px 8px;font-size:10px;" onclick="lockOwnerSettings()">Lock</button>
