function hydrateContactMessages(c, allLiLogs) {
  let msgs = [];
  try {
    if (c.messages_json && String(c.messages_json).trim().startsWith('[')) {
      msgs = JSON.parse(c.messages_json);
    }
  } catch (e) { msgs = []; }

  if (!Array.isArray(msgs) || msgs.length === 0) {
    if (seededMemberReplies[c.contact_id]) {
      msgs = [...seededMemberReplies[c.contact_id]];
    } else {
      const slug = String(c.target_profile_url || '').toLowerCase().replace(/\/+$/, '').split('/in/')[1] || '';
      const relatedLogs = (allLiLogs || []).filter(l => {
        const lSlug = String(l.target_profile_url || '').toLowerCase().replace(/\/+$/, '').split('/in/')[1] || '';
        return (slug && lSlug && slug === lSlug) || (c.person_name && String(l.insider_name || '').toLowerCase().includes(String(c.person_name).toLowerCase()));
      });
      for (const rl of relatedLogs) {
        if (rl.post_snippet) {
          msgs.push({
            sender: 'them',
            author: c.person_name,
            text: `[${rl.activity_type === 'Post Comment' ? 'LinkedIn Post' : 'Activity Context'}] ${rl.post_snippet}`,
            ts: String(rl.activity_date || '2026-10-05').slice(0, 10),
            channel: rl.activity_type || 'LinkedIn Activity',
            status: 'Gathered from LinkedIn'
          });
        }
        if (rl.content_text) {
          msgs.push({
            sender: 'me',
            author: 'You (Sumanto)',
            text: rl.content_text,
            ts: String(rl.activity_date || '2026-10-05').slice(0, 10),
            channel: rl.activity_type || 'Outreach',
            status: rl.approval_status || 'Drafted'
          });
        }
      }
      if (msgs.length === 0 && c.connection_note) {
        msgs.push({
          sender: 'me',
          author: 'You (Sumanto)',
          text: c.connection_note,
          ts: String(c.updated_at || '2026-10-06').slice(0, 10),
          channel: 'Initial Icebreaker / DM',
          status: /CONFIRMED/i.test(String(c.execution_status || '')) ? 'Sent on LinkedIn' : (c.approval_status || 'Ready to Send')
        });
      }
    }
  }
  c.messages = msgs;
  c.messages_json = JSON.stringify(msgs);
  return msgs;
}

