// Parse Gemini LLM Rule Synthesizer & Section Rewriter output (if executed)
let llmOut = {};
try {
  const rawCand = $input.first()?.json?.candidates?.[0]?.content?.parts?.[0]?.text || '';
  if (rawCand) {
    llmOut = JSON.parse(String(rawCand).replace(/```json|```/gi, '').trim());
  }
} catch (e) { llmOut = {}; }

const synthesizeLlmRule = (rawText, secHint) => {
  const raw = String(rawText || '').trim();
  const sec = String(llmOut.section_name || secHint || 'global').trim();
  const secUpper = sec.toUpperCase();
  if (llmOut.synthesized_rule && String(llmOut.synthesized_rule).trim().length > 12 && String(llmOut.synthesized_rule).trim().toLowerCase() !== raw.toLowerCase()) {
    return { section: sec, rule: String(llmOut.synthesized_rule).trim() };
  }
  if (/stat|number|data|1m\+|40%|percent/i.test(raw) && (/summary/i.test(raw) || /summary/i.test(sec))) {
    return {
      section: 'summary',
      rule: 'SUMMARY — NO STATISTICS OR NUMERICAL METRICS DIRECTIVE: NEVER include percentages, numbers, record volumes, or quantitative metrics (such as "1M+ monthly records", "40%", "25%–30%", "84%", or "15+ launches") in the Summary section; reserve all numerical metrics strictly for the Experience section bullets. Instead, write a qualitative 3-sentence Summary grounded in Sumanto\x27s past experience across enterprise SQL/Python analytics, Tableau BI reporting, workflow automation, and stakeholder consulting, tailored directly to the current Job Description.'
    };
  }
  const quoted = [];
  const withoutQuotes = raw.replace(/like\s*[-:]?\s*["“](.*?)["”]/gi, (_, q) => {
    quoted.push(q.trim().slice(0, 90));
    return '';
  }).replace(/["“](.*?)["”]/g, (_, q) => {
    if (q.length > 25) { quoted.push(q.trim().slice(0, 90)); return ''; }
    return `"${q}"`;
  }).trim();

  const clauses = withoutQuotes.split(/(?:\.|\n|;)+/).map(s => s.trim()).filter(Boolean);
  const formattedClauses = clauses.map(c => {
    if (/^(don't|do not|never|avoid|no\s+)/i.test(c)) {
      return 'NEVER ' + c.replace(/^(don't|do not|never|avoid|no)\s+/i, '').trim();
    }
    if (/^(use|always|include|keep|make sure|ensure|start|open|write)\b/i.test(c)) {
      return 'ALWAYS ' + c.replace(/^always\s+/i, '').trim();
    }
    return 'MUST ' + c;
  });
  const banSuffix = quoted.length ? ` (specifically prohibit patterns such as "${quoted[0]}...")` : '';
  const bodyDirective = formattedClauses.join('; and ') || (`Follow constraint: ${withoutQuotes}`);
  return {
    section: sec === 'auto' ? (/summary/i.test(raw) ? 'summary' : (/skill/i.test(raw) ? 'core_skills' : (/experience|bullet/i.test(raw) ? 'experience' : 'global'))) : sec,
    rule: `${secUpper} — MANDATORY LLM DIRECTIVE: ${bodyDirective}${banSuffix}. Enforce this rule strictly across all future generations.`
  };
};

