  if (rg.resume_id) resById[String(rg.resume_id).trim().toUpperCase()] = rg;
}

const clBySno = {};
const clById = {};
for (const cg of clGens) {
  if (cg.s_no && !clBySno[String(cg.s_no).trim()]) clBySno[String(cg.s_no).trim()] = cg;
  if (cg.resume_id && !clById[String(cg.resume_id).trim().toUpperCase()]) clById[String(cg.resume_id).trim().toUpperCase()] = cg;
}

const buildMergedJobs = () => {
  const jobs = [];
  for (const r of rawSheetRows) {
    const sNo = String(r['S. No.'] || '').trim();
    const company = String(r['Company'] || '').trim();
    const title = String(r['Position - Title'] || '').trim();
    if (!sNo || (!company && !title)) continue;

    const resumeId = String(r['Resume_id'] || `RES-${sNo}`).trim();
    const rg = resById[resumeId.toUpperCase()] || resBySno[sNo] || {};
    const cg = clById[resumeId.toUpperCase()] || clBySno[sNo] || {};

    const resumeLink = String(r['Resume'] || rg.drive_web_link || '').trim();
    const resumeDriveId = extractDriveId(rg.drive_file_id) || extractDriveId(resumeLink);

    const clLink = String(r['Cover Letter'] || cg.cl_drive_web_link || '').trim();
    const clDriveId = extractDriveId(cg.cl_drive_file_id) || extractDriveId(clLink);

    const rawStatus = String(r['Status'] || 'Pending Review').trim();
    const resumeStatus = String(r['Resume Status'] || rg.resume_status || 'Generated').trim();
    const clStatus = String(r['Cover Letter Status'] || cg.cl_status || (clDriveId ? 'Generated' : 'Not Created')).trim();

    const stLow = `${rawStatus} ${resumeStatus}`.toLowerCase();
    let stageBucket = 'Pending Review';
    if (/re-?apply/i.test(rawStatus)) {
      stageBucket = 'Re-apply';
    } else if (stLow.includes('reject') || stLow.includes('declin') || stLow.includes('closed') || stLow.includes('not selected')) {
      stageBucket = 'Rejected';
    } else if (stLow.includes('offer') || stLow.includes('selected') || stLow.includes('hired')) {
      stageBucket = 'Offer';
    } else if (stLow.includes('interview') || stLow.includes('round') || stLow.includes('assessment') || stLow.includes('screen') || stLow.includes('shortlist')) {
      stageBucket = 'Interviewing';
    } else if (stLow.includes('applied') || stLow.includes('submitted') || String(r['Applied On'] || '').trim() !== '') {
      stageBucket = 'Applied';
    } else if (stLow.includes('approved') || stLow.includes('lgtm') || stLow.includes('queued')) {
      stageBucket = 'Approved / Queued';
    } else if (stLow.includes('rework') || stLow.includes('revision')) {
      stageBucket = 'Needs Rework';
    } else if (stLow.includes('skip') || stLow.includes('hold') || stLow.includes('pause')) {
      stageBucket = 'Skipped / Hold';
    }

    jobs.push({
      sNo,
      sNoNum: parseInt(sNo.replace(/[^0-9]/g, ''), 10) || 0,
      resumeId,
      company,
      industry: String(r['Industry'] || 'Technology & Data Analytics').trim(),
      jobId: String(r['Job ID'] || rg.job_id || '').trim(),
      title,
      jd: String(r['Position - Description'] || '').trim(),
      location: String(r['Location'] || r['Position - Location'] || 'India / Global Remote').trim(),
      portal: String(r['Applied From'] || 'LinkedIn Jobs').trim(),
      jdUrl: String(r['Applied Page link'] || r['Company website'] || '').trim(),
      status: rawStatus,
      stageBucket,
      resumeStatus,
      clStatus,
      combinedDocStatus: String(r['Status of Resume and CL'] || '').trim(),
      appliedOn: String(r['Applied On'] || '').trim(),
      followUpDate: String(r['Follow up Date'] || '').trim(),
      createdOn: String(r['Created On'] || (rg.updated_at ? String(rg.updated_at).slice(0, 10) : todayIso)).trim(),
      lastUpdated: String(r['Last Updated'] || (rg.updated_at ? String(rg.updated_at).slice(0, 16).replace('T', ' ') : nowIstStamp)).trim(),
      reference: String(r['Reference'] || '').trim(),
      hrName: String(r['HR'] || '').trim(),
      hrEmail: String(r['HR Email'] || '').trim(),
      hrPhone: String(r['Number'] || '').trim(),
      reviewerNotes: String(r['Notes by Reviewer'] || r['Notes for Resume'] || '').trim(),
      clNotes: String(r['Notes for CL'] || cg.last_review_note || '').trim(),
      generalNotes: String(r['Notes'] || '').trim(),
      aboutCompany: String(r['About Company'] || '').trim(),
      resumeDriveId,
      resumeLink,
      resumePreviewUrl: resumeDriveId ? `https://drive.google.com/file/d/${resumeDriveId}/preview` : '',
      clDriveId,
      clLink,
      clPreviewUrl: clDriveId ? `https://drive.google.com/file/d/${clDriveId}/preview` : '',
      roleCategory: String(rg.role_category || 'Data & Business Analytics').trim(),
      extractedKeywords: String(rg.extracted_jd_keywords || '').trim(),
      revisionCount: Number(rg.revision_count || 1),
      clRevisionCount: Number(cg.revision_count || 1),
      resumeSections: {
        summary_html: rg.summary_html || buildQualitativeSummary(title, r['Position - Description']),
        skills_html: rg.skills_html || `<ul><li><strong>Data Analysis &amp; Database Management:</strong> SQL (PostgreSQL, MySQL, BigQuery), Python (Pandas, NumPy), R, Excel, Jupyter Notebooks, API/Data Integration, Database Management</li><li><strong>Business Intelligence &amp; Visualization:</strong> KPI Scorecard Design, Tableau, Looker Studio, Dashboard/Report Automation, Interactive Dashboards, Executive Presentations</li><li><strong>Data Governance &amp; Process Optimization:</strong> Data Cleaning &amp; Wrangling, Data Transformation, Quality Assurance, Automating Workflows (n8n), Root-Cause &amp; Variance Analysis</li><li><strong>Stakeholder Collaboration &amp; Strategy:</strong> Cross-Functional Teamwork, Stakeholder Communication, Consulting &amp; Client Engagement, Training &amp; Mentorship, Business Acumen</li></ul>`,
        experience_html: rg.experience_html || `<div class="job-block"><div class="job-header"><span class="job-title"><strong>Sr. Data Analyst, Highspring India – Gurugram, India</strong></span><span class="job-date"><strong>Oct 2025 - Present</strong></span></div><ul><li>Spearheaded end-to-end <strong>funnel and behavioral analytics</strong> across 1M+ monthly records using SQL and Python, uncovering conversion bottlenecks and cutting manual reporting overhead by 40%.</li><li>Designed and deployed interactive <strong>Tableau dashboards</strong> and automated KPI reporting suites across 15+ cross-functional launches, accelerating leadership decision cycles.</li><li>Conducted deep-dive <strong>root-cause analysis</strong> and customer segmentation across multi-source datasets, partnering with engineering and business teams to maintain 95% delivery quality.</li></ul></div><div class="job-block"><div class="job-header"><span class="job-title"><strong>Lead Trainer, Concentrix Daksh – Gurugram, India</strong></span><span class="job-date"><strong>April 2022 – Aug 2025</strong></span></div><ul><li>Built automated <strong>performance analytics</strong> trackers and Excel/SQL competency matrices across 200+ specialists, boosting new-hire quality scores by 84% within two quarters.</li><li>Led <strong>diagnostic gap analysis</strong> on operational SLA and quality telemetry, redesigning process workflows to reduce recurring knowledge and execution gaps by 30%.</li><li>Partnered with global operations stakeholders on <strong>capacity planning</strong> and workflow standardization, driving a 25% increase in team productivity and throughput.</li></ul></div><div class="job-block"><div class="job-header"><span class="job-title"><strong>Customer Support Representative, Concentrix Daksh – Gurugram, India</strong></span><span class="job-date"><strong>Jan 2021 – Mar 2022</strong></span></div><ul><li>Resolved escalated consumer inquiries by utilizing <strong>CRM telemetry</strong> and historical performance metrics, accelerating ticket resolution speed by 35% across high-volume queues.</li><li>Analyzed user interaction trends to identify recurring <strong>service bottlenecks</strong>, partnering with operations leads to streamline workflows and boost customer satisfaction.</li></ul></div><div class="job-block"><div class="job-header"><span class="job-title"><strong>Founder | Creative Director, Maerke Stratcomm – New Delhi, India</strong></span><span class="job-date"><strong>June 2010 – July 2020</strong></span></div><ul><li>Directed <strong>commercial analytics</strong>, pricing strategy, and market segmentation for 15+ B2B and retail clients, driving a 30% increase in customer acquisition.</li><li>Implemented <strong>funnel performance tracking</strong> and ROI attribution models across regional distribution channels, expanding HORECA and enterprise account revenue by 25%.</li></ul></div>`,
        certifications_html: rg.certifications_html || `<div class="cert-row"><span class="cert-name">Coursera - Tableau Business Intelligence Analyst Professional Certificate</span><span class="cert-date">May 2025</span></div><div class="cert-row"><span class="cert-name">Coursera - Google Advanced Data Analytics</span><span class="cert-date">In Progress</span></div><div class="cert-row"><span class="cert-name">Coursera - Google Project Management</span><span class="cert-date">In Progress</span></div>`,
        education_html: rg.education_html || `<div class="edu-row"><span>University of Delhi, B.Comm(Hons.)</span><span class="edu-date">2013 – 2016</span></div>`,
        hobbies_html: rg.hobbies_html || `<div class="hobbies-line">Practicing Buddhism &nbsp;|&nbsp; Automating life with n8n &nbsp;|&nbsp; Growing Mushrooms</div>`
      },
      clSections: {
        hasStoredCl: Boolean(cg.para1_hook_html || clDriveId),
        salutation_html: cg.salutation_html || `<p class="salutation">Dear Hiring Manager at ${company},</p>`,
        para1_hook_html: cg.para1_hook_html || `<p>I am writing to apply for the ${title || 'Senior Data & Business Analyst'} role at ${company}. With over five years of hands-on experience building reliable SQL and Python reporting pipelines, designing executive Tableau dashboards, and partnering with product and operations leaders, I am eager to contribute immediately to ${company}'s data and analytics goals.</p>`,
        para2_stewardship_html: cg.para2_stewardship_html || `<p>Throughout my career across high-volume operational and business intelligence environments, I have focused on turning complex, fragmented datasets into clear, trustworthy decision frameworks. Whether automating recurring ETL workflows or establishing governed KPI definitions across teams, I prioritize data accuracy and practical business impact.</p>`,
        para3_impact_story_html: cg.para3_impact_story_html || `<p>In my recent work, I re-engineered manual reporting workflows into automated SQL and Tableau pipelines that reduced reporting latency by over 40% while uncovering key drivers of funnel conversion and SLA performance. This blend of technical execution and stakeholder communication aligns closely with what ${company} seeks in this position.</p>`,
        para4_resilience_html: cg.para4_resilience_html || `<p>I thrive in fast-paced environments where requirements evolve quickly and cross-functional clarity is essential. My background spans end-to-end requirement gathering, UAT governance, root-cause diagnostics, and translating technical findings for non-technical leadership.</p>`,
        para5_closing_html: cg.para5_closing_html || `<p>Thank you for your time and consideration. I would welcome the opportunity to discuss how my background in SQL, Python, Tableau, and business analysis can support ${company}'s upcoming initiatives.</p>`
      }
    });
  }
  jobs.sort((a, b) => a.sNoNum - b.sNoNum);
  return jobs;
};

