      </div>
    </body></html>`;
  } else {
    const rs = j.resumeSections || {};
    renderedPdfFileName = docType === 'master' ? 'Sumanto_Banerjee-Master_Resume.pdf' : `Sumanto_Banerjee-Resume-${cleanComp}.pdf`;
    docHtml = `<!DOCTYPE html><html><head><meta charset="UTF-8"><style>${pdfCss}</style></head><body>
      <div class="resume-header">
        <h1>Sumanto Banerjee</h1>
        <div class="contact-line">user@example.com &nbsp;|&nbsp; +91-8802444912 &nbsp;|&nbsp; <a href="https://www.linkedin.com/in/sumanto-banerjee/">Linkedin Profile</a></div>
