      ${rs.hobbies_html || ''}
    </body></html>`;
  }

  try {
    const boundary = '----CareerPulseGotenberg' + Date.now();
    const CRLF = '\r\n';
    const bodyStr =
      '--' + boundary + CRLF +
      'Content-Disposition: form-data; name="files"; filename="index.html"' + CRLF +
      'Content-Type: text/html; charset=utf-8' + CRLF + CRLF +
      docHtml + CRLF +
      '--' + boundary + CRLF +
      'Content-Disposition: form-data; name="paperWidth"' + CRLF + CRLF + '8.27' + CRLF +
      '--' + boundary + CRLF +
