}

if (action === 'update_job') {
  const sNo = String(body.sNo || '').trim();
  const subAction = String(body.subAction || 'set_status').trim();
  const targetRow = rawSheetRows.find(r => String(r['S. No.'] || '').trim() === sNo) || {};
  const company = String(targetRow['Company'] || body.company || 'Target').trim();
  const curSt = String(targetRow['Status'] || '').trim();
  const wasAlreadyApplied = (/applied|submitted|interview|offer/i.test(curSt) || String(targetRow['Applied On'] || '').trim() !== '') && !/re-?apply/i.test(curSt);

  if (subAction === 'apr_res' || subAction === 'apr_res_cl') {
    const withCl = subAction === 'apr_res_cl';
    const nextSt = wasAlreadyApplied ? (curSt || 'Applied') : (withCl ? 'Pending CL Review' : 'Approved - Queued for Auto-Apply');
    const patch = {
      'S. No.': sNo,
      'Resume Status': 'LGTM',
      'Status': nextSt,
      'Status of Resume and CL': withCl ? 'Pending CL Review' : 'Approved',
      'Last Updated': nowIstStamp
    };
    if (withCl) patch['Cover Letter Status'] = 'Create one';
    targetRow['Resume Status'] = 'LGTM';
    targetRow['Status'] = nextSt;
    sheetUpdates.push(patch);
    sqlQueries.push(`UPDATE resume_generations SET resume_status = 'Approved', updated_at = NOW() WHERE s_no = '${esc(sNo)}' OR resume_id = 'RES-${esc(sNo)}';`);
    targetWorkflowId = withCl ? 'T4k9rXZ2CKK72xZS' : 'lXNGL9OcyVVtCBuz';
    apiMessage = wasAlreadyApplied
      ? `✅ Approved Resume #${sNo} (${company})! (🔒 Locked as '${nextSt}' — will NOT re-apply unless manually changed to 'Re-apply').`
      : (withCl
          ? `Approved Resume #${sNo} (${company}) & triggered Cover Letter generation (WF3)!`
          : `Approved Resume #${sNo} (${company}) — Queued for Auto-Apply & Few-Shot Learning (WF2)!`);
  } else if (subAction === 'apr_cl') {
    const nextSt = wasAlreadyApplied ? (curSt || 'Applied') : 'Approved - Queued for Auto-Apply';
    targetRow['Cover Letter Status'] = 'LGTM';
    targetRow['Status'] = nextSt;
    sheetUpdates.push({
      'S. No.': sNo,
      'Cover Letter Status': 'LGTM',
      'Status': nextSt,
      'Status of Resume and CL': 'Approved',
      'Last Updated': nowIstStamp
    });
    sqlQueries.push(`UPDATE cover_letter_generations SET cl_status = 'Approved', updated_at = NOW() WHERE s_no = '${esc(sNo)}' OR resume_id = 'RES-${esc(sNo)}';`);
    if (!wasAlreadyApplied) targetWorkflowId = 'T4k9rXZ2CKK72xZS';
    apiMessage = wasAlreadyApplied
      ? `✅ Approved Cover Letter #${sNo} (${company})! (🔒 Locked as '${nextSt}' — will NOT re-apply unless manually set to 'Re-apply').`
      : `Approved Cover Letter #${sNo} (${company}) — Queued for Auto-Apply!`;
  } else if (subAction === 'generate_cl') {
    sheetUpdates.push({
      'S. No.': sNo,
      'Cover Letter Status': 'Create one',
      'Status': wasAlreadyApplied ? (curSt || 'Applied') : 'Pending CL Review',
      'Last Updated': nowIstStamp
    });
    targetWorkflowId = 'T4k9rXZ2CKK72xZS';
    apiMessage = `Triggered 1-Page Cover Letter generation (Workflow 3) for #${sNo} (${company})!`;
  } else {
    const newStatus = String(body.status || '').trim();
    const patch = { 'S. No.': sNo, 'Last Updated': nowIstStamp };
    if (newStatus) {
      if (wasAlreadyApplied && /queued|auto-apply/i.test(newStatus) && !/re-?apply/i.test(newStatus)) {
        apiSuccess = false;
        apiMessage = `🔒 Job #${sNo} (${company}) is already Applied! It will not re-apply unless you manually change its stage to 'Re-apply'.`;
      } else {
        patch['Status'] = newStatus;
        targetRow['Status'] = newStatus;
      }
    }
    if (newStatus.toLowerCase().includes('applied') && !targetRow['Applied On']) {
      patch['Applied On'] = todayMDY;
      targetRow['Applied On'] = todayMDY;
    }
    if (body.resumeStatus !== undefined) { patch['Resume Status'] = String(body.resumeStatus); targetRow['Resume Status'] = String(body.resumeStatus); }
    if (body.clStatus !== undefined) { patch['Cover Letter Status'] = String(body.clStatus); targetRow['Cover Letter Status'] = String(body.clStatus); }
    if (body.followUpDate !== undefined) { patch['Follow up Date'] = String(body.followUpDate); targetRow['Follow up Date'] = String(body.followUpDate); }
    if (body.reference !== undefined) { patch['Reference'] = String(body.reference); targetRow['Reference'] = String(body.reference); }
    if (body.hrName !== undefined) { patch['HR'] = String(body.hrName); targetRow['HR'] = String(body.hrName); }
    if (body.hrEmail !== undefined) { patch['HR Email'] = String(body.hrEmail); targetRow['HR Email'] = String(body.hrEmail); }
    if (body.hrPhone !== undefined) { patch['Number'] = String(body.hrPhone); targetRow['Number'] = String(body.hrPhone); }
    if (body.generalNotes !== undefined) { patch['Notes'] = String(body.generalNotes); targetRow['Notes'] = String(body.generalNotes); }
    if (apiSuccess) {
